import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Plugin build tool","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/build/docs/index.md"},"headers":[],"relativePath":"tools/build/docs/index.md","filePath":"tools/build/docs/index.md","lastUpdated":1792268904000}`),a={name:`tools/build/docs/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plugin-build-tool" tabindex="-1">Plugin build tool <a class="header-anchor" href="#plugin-build-tool" aria-label="Permalink to “Plugin build tool”">​</a></h1><p><code>@pumpkin-plugins/build</code> turns a plugin&#39;s TypeScript entry point into a Pumpkin WebAssembly component. It bundles the plugin, adds the WASI imports declared in the package configuration, and uses the selected engine to componentize the bundle with the repository&#39;s pinned toolchain. You can also use it to generate guest declarations for typechecking.</p><h2 id="build-a-plugin" tabindex="-1">Build a plugin <a class="header-anchor" href="#build-a-plugin" aria-label="Permalink to “Build a plugin”">​</a></h2><p>Run <code>pnpm build</code> from a plugin package. The <code>pumpkinPlugin</code> object in its <code>package.json</code> selects the entry point, output file, requested WASI capabilities, and optional engine. The output is the configured <code>.wasm</code> component under the package&#39;s build directory.</p><p>The engine defaults to <code>static-hermes</code>; set it to <code>quickjs</code> to build with QuickJS. Both engines are supported, and current plugin packages use Static Hermes. Static Hermes is the WASI 2 backend described in the <a href="./../../static-hermes-runtime/README">runtime guide</a>. It uses the lean runtime profile and Hades garbage collection by default. Set <code>staticHermesRuntime</code> to <code>&quot;full&quot;</code> to retain runtime source compilation, or set <code>STATIC_HERMES_ENABLE_LEAN_ARCHIVE=0</code> to select the full profile for builds. Set <code>staticHermesGc</code> to <code>&quot;malloc&quot;</code> to use malloc-managed garbage collection.</p><p>The executable is compiled from TypeScript to <code>dist/cli.js</code>. Repository-wide build and typecheck commands compile it before consumers run. After a fresh checkout, build the runtime and CLI before running a direct workspace package command:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/static-hermes-runtime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>Run <code>pumpkin-plugins-build --help</code> to see the available options or <code>--version</code> to see the installed tool version.</p><p>Run <code>pumpkin-plugins-build --types-only</code> to generate guest declarations without building the component. TypeScript and your editor consume these declarations. They are build output, so make changes in your plugin source and package configuration rather than editing the generated files.</p><p>Pass <code>--parse-ts</code> to use Hermes&#39;s partial, unstable TypeScript parser when compiling a Static Hermes component bundle. The option is off by default and cannot be used with QuickJS.</p><p>The build tool reports progress for both engines with a shared <code>[build]</code> prefix, including the entry point, selected runtime, componentization stage, and final artifact size. It suppresses routine output from the QuickJS and Static Hermes toolchains; if a tool fails, its captured stderr appears in the build output.</p><p>In an interactive terminal, the executable checks npm for a newer builder release in the background and may print an update notice. Results are cached for three hours, and registry errors do not affect the build. Pass <code>--no-update-cache</code> to check npm without reading or writing the cache. The check is skipped for help and version output, CI, development mode (<code>PUMPKIN_DEV_MODE=1</code>), and non-interactive output. To opt out, pass <code>--no-update-notifier</code> or set <code>PUMPKIN_PLUGINS_NO_UPDATE_NOTIFIER=1</code>. If you see an update notice, preview the migration from the plugin directory with <code>pnpm dlx @pumpkin-plugins/codemod update-build .</code>.</p><h2 id="wasi-capability-metadata" tabindex="-1">WASI capability metadata <a class="header-anchor" href="#wasi-capability-metadata" aria-label="Permalink to “WASI capability metadata”">​</a></h2><p>The builder and migration codemod use the shared, dependency-free <a href="./../../wasi-capabilities/README"><code>@pumpkin-plugins/wasi-capabilities</code></a> package for capability names, WIT interfaces, and the pinned WASI version. These capabilities describe the services a plugin needs; they do not infer its Pumpkin permissions.</p><h2 id="build-constraints" tabindex="-1">Build constraints <a class="header-anchor" href="#build-constraints" aria-label="Permalink to “Build constraints”">​</a></h2><p>Static Hermes uses the pinned Pumpkin API WIT and WASI 2. Keep the workspace&#39;s Pumpkin API version aligned with the test harness server version. Declare the WASI capabilities and Pumpkin permissions required by the APIs your plugin uses.</p><p>Building the same source twice does not guarantee identical bytes. For signing or publishing, use the exact artifact produced by the build job instead of rebuilding it later.</p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};